input.command:
$urls = @(
  "https://web.archive.org/cdx/search/cdx?url=phsta.org/*&matchType=domain&output=text&fl=original,timestamp,statuscode&limit=50&filter=statuscode:200",
  "https://web.archive.org/cdx/search/cdx?url=*.phsta.*&output=text&fl=original,timestamp,statuscode&limit=50",
  "https://web.archive.org/cdx/search/cdx?url=*travaglini*&output=text&fl=original,timestamp,statuscode&limit=50&filter=statuscode:200",
  "https://web.archive.org/cdx/search/cdx?url=*breezewood*trial*&output=text&fl=original,timestamp,statuscode&limit=50",
  "https://web.archive.org/cdx/search/cdx?url=*highscoreterrier*&output=text&fl=original,timestamp,statuscode&limit=50"
)
$i=0
foreach ($u in $urls) {
  $i++
  Write-Output "=== QUERY $i ==="
  Write-Output $u
  try {
    $r = Invoke-WebRequest -Uri $u -TimeoutSec 90 -UseBasicParsing
    if ([string]::IsNullOrWhiteSpace($r.Content)) { Write-Output "(empty)" } else { Write-Output $r.Content.Substring(0, [Math]::Min(4000, $r.Content.Length)) }
  } catch { Write-Output ("ERROR: " + $_.Exception.Message) }
}

$apis = @(
  "https://archive.org/advancedsearch.php?q=%28Breezewood+AND+%28terrier+OR+PHSTA+OR+Travaglini+OR+%22Jack+Russell%22%29%29&fl[]=identifier&fl[]=title&fl[]=description&fl[]=mediatype&rows=50&page=1&output=json",
  "https://archive.org/advancedsearch.php?q=%22Pennsylvania+High+Score+Terrier%22&fl[]=identifier&fl[]=title&fl[]=description&fl[]=mediatype&rows=25&page=1&output=json",
  "https://archive.org/advancedsearch.php?q=PHSTA+terrier&fl[]=identifier&fl[]=title&fl[]=description&fl[]=mediatype&rows=25&page=1&output=json"
)
foreach ($a in $apis) {
  Write-Output "=== API ==="
  try {
    $r = Invoke-WebRequest -Uri $a -TimeoutSec 60 -UseBasicParsing
    Write-Output $r.Content.Substring(0, [Math]::Min(5000, $r.Content.Length))
  } catch { Write-Output ("ERROR: " + $_.Exception.Message) }
}

